-- 197: publish the Magical Hat (Nix) as an ANIMATED cosmetic.
--
-- RUN THIS WITH THE RELEASE THAT SHIPS THE ART, NOT BEFORE.
-- The 10 frames reach players only through `cosmetics.zip` attached to the
-- GitHub release (CustomCosmetics.cs fetches
-- releases/latest/download/cosmetics.zip when art is missing). Flipping
-- catalog_ready ahead of that zip is exactly the #163 failure: the item becomes
-- visible and purchasable while no client can render it, and Home falls back to
-- a green swatch.
--
-- ── What changed and why ───────────────────────────────────────────────────
-- Sid approved submission 16 ("Magical Hat", sku face_detail_magical_hat) on
-- 2026-08-06 as a STATIC image. The artist wanted it animated, so the art is
-- replaced with a 10-frame set built from their GIF. Safe to do because this
-- sku has never shipped: published_placement_revision = 0 and
-- catalog_ready = FALSE, so no client holds the old art and there is no
-- version skew to manage (#164/#165).
--
-- PLACEMENT IS UNCHANGED. approved_render_scale (1.3) and the approved offsets
-- (0, 0) are reused verbatim; the client CosmeticDef copies those same numbers.
-- Measured before rebuilding the art: the static PNG filled 97.5% of its canvas
-- centred at (0.501, 0.469) and the animated frames fill 97.1% centred at
-- (0.499, 0.470), i.e. the same framing, so the reviewed placement still
-- describes what renders. Nothing here advances placement_revision or
-- approved_placement_revision — the artist's approved proposal is untouched.
--
-- Idempotent: every statement is a conditional UPDATE, so the deploy wrapper's
-- double-run (#243) is a no-op the second time.

BEGIN;

-- 1. Replace the approval record's stored image with frame 1 of the animation.
--    The submissions table holds ONE image (#161 — it is not an animation
--    pipeline), and the approved static drawing differs from frame 1 in 3.02%
--    of its pixels with a max channel delta of 255, i.e. it is a genuinely
--    different drawing rather than the same pose. Left alone, the admin review
--    preview and any future placement re-derivation would keep showing art that
--    no longer ships.
UPDATE cosmetic_submissions
   SET png_data  = '\'::bytea,
       png_bytes = 22100
 WHERE id = 16
   AND shop_sku = 'face_detail_magical_hat';

-- 2. GUARD: the compiled placement must still be the approved one.
--    ship.md requires a release migration to abort if the artist submitted a
--    newer revision AFTER the bundle was cut — otherwise the client ships one
--    scale/offset while the database claims another is live, which is exactly
--    the three-state drift #165 exists to prevent.
--
--    The values below are what plugin/CustomCosmetics.cs actually compiles for
--    this sku: Scale = 1.3f, Offset = Vector2.zero, from approved revision 1.
DO $$
DECLARE
    s NUMERIC; ox NUMERIC; oy NUMERIC; rev INTEGER;
BEGIN
    SELECT approved_render_scale, approved_render_offset_x,
           approved_render_offset_y, approved_placement_revision
      INTO s, ox, oy, rev
      FROM cosmetic_submissions
     WHERE shop_sku = 'face_detail_magical_hat';

    IF rev IS NULL THEN
        RAISE EXCEPTION 'migration 197: no approved placement for the Magical Hat';
    END IF;
    IF rev <> 1 OR s <> 1.3 OR ox <> 0 OR oy <> 0 THEN
        RAISE EXCEPTION
            'migration 197: approved placement moved since the bundle was cut '
            '(rev=% scale=% offset=%,% — client compiled rev=1 scale=1.3 offset=0,0). '
            'Re-bundle the PNG and CosmeticDef before publishing.', rev, s, ox, oy;
    END IF;
END $$;

-- 3. Publish. Flipping catalog_ready IS the act of publishing, and the
--    migration-148 trigger (trg_shop_item_catalog_release) stamps BOTH
--    released_at and published_placement_revision from the approved revision
--    when it flips. An earlier draft set published_placement_revision by hand
--    first; that duplicated the trigger and contradicted ship.md's explicit
--    "do NOT set released_at or published_placement_revision by hand". Removed
--    — the post-check below now TESTS that the trigger fired rather than
--    re-doing its work.
--
--    stock_limit is left alone so the item stays the deliberate "coming soon"
--    tease until the artist opens sales from the Artist tab (#164).
UPDATE shop_items
   SET catalog_ready = TRUE
 WHERE sku = 'face_detail_magical_hat';

-- ── Post-check ─────────────────────────────────────────────────────────────
DO $$
DECLARE
    ok_ready   BOOLEAN;
    ok_rev     BOOLEAN;
    stock      INTEGER;
    nbytes     INTEGER;
BEGIN
    SELECT catalog_ready, stock_limit INTO ok_ready, stock
      FROM shop_items WHERE sku = 'face_detail_magical_hat';
    IF ok_ready IS NULL THEN
        RAISE EXCEPTION 'migration 197: shop row face_detail_magical_hat is missing';
    END IF;
    IF NOT ok_ready THEN
        RAISE EXCEPTION 'migration 197: catalog_ready did not flip';
    END IF;

    -- This asserts the TRIGGER did its job; nothing in this file sets it.
    SELECT (published_placement_revision = approved_placement_revision), png_bytes
      INTO ok_rev, nbytes
      FROM cosmetic_submissions WHERE id = 16;
    IF NOT COALESCE(ok_rev, FALSE) THEN
        RAISE EXCEPTION
            'migration 197: trg_shop_item_catalog_release did not stamp '
            'published_placement_revision — the trigger may be missing';
    END IF;
    IF nbytes <> 22100 THEN
        RAISE EXCEPTION 'migration 197: png_data replacement did not take (bytes=%)', nbytes;
    END IF;

    -- Informational: the tease state is intentional, so say so rather than
    -- letting a future reader assume the sale was forgotten.
    RAISE NOTICE 'migration 197 OK — Magical Hat renderable (10 frames @ 2.5fps), stock_limit=% (-1 = not on sale yet, by design)', stock;
END $$;

COMMIT;
